import bpy, os, json
from mathutils import Vector
from mathutils.bvhtree import BVHTree
EXPECTED=os.path.normcase(os.path.normpath(r'C:\mcp-blender\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=EXPECTED: raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')
terrain=bpy.data.objects.get('WORLD | TERRENO MASTER | blockout'); tower=bpy.data.objects.get('V4 | torre documental'); hall=bpy.data.objects.get('V4 | hall piso terreo marcador')
low=bpy.data.collections.get('D | ESTACAO CIDADE BAIXA | blockout v1'); elev=bpy.data.collections.get('01 WORLD | ELEVADOR LACERDA | blockout v4')
if not all((terrain,tower,hall,low,elev)): raise RuntimeError('base incompleta')
verts=[terrain.matrix_world@v.co for v in terrain.data.vertices]; polys=[tuple(p.vertices) for p in terrain.data.polygons]; bvh=BVHTree.FromPolygons(verts,polys,all_triangles=False)
def rayz(x,y):
    h=bvh.ray_cast(Vector((x,y,250)),Vector((0,0,-1)),600); return None if h[0] is None else float(h[0].z)
def zmin(o): return min((o.matrix_world@Vector(c)).z for c in o.bound_box)
T=tower.matrix_world.translation.xy.copy(); EX=(hall.matrix_world.translation.xy-T).normalized(); EY=Vector((-EX.y,EX.x))
def coords(o):
    p=o.matrix_world.translation.xy-T; return float(p.dot(EX)),float(p.dot(EY))
def row(o):
    s,l=coords(o); p=o.matrix_world.translation; tz=rayz(p.x,p.y); lo=zmin(o)
    return {'name':o.name,'type':o.type,'s_high_axis_m':round(s,3),'lateral_m':round(l,3),'origin_xy':[round(p.x,3),round(p.y,3)],'zmin':round(lo,3),'terrain_z':None if tz is None else round(tz,3),'gap_bottom':None if tz is None else round(lo-tz,3),'dims':[round(float(v),3) for v in o.dimensions]}
low_props={k:low[k] for k in low.keys()}
low_objs=sorted([row(o) for o in low.objects if o.type in {'MESH','FONT','CURVE'}],key=lambda r:(r['s_high_axis_m'],r['lateral_m']))
# objetos diretos V4 associados a acesso/estacao/hall/piso/cobertura
upper=[]
for o in elev.objects:
    n=o.name.lower()
    if any(k in n for k in ('hall','estacao','estação','piso','entrada','marquise','terminal','parede fundo','parede frente')):
        if o.type in {'MESH','FONT','CURVE'}: upper.append(row(o))
upper=sorted(upper,key=lambda r:(r['s_high_axis_m'],r['lateral_m']))
# perfil mais longo na direção Cidade Alta
profile=[]
for s in range(35,61):
    p=T+EX*s; z=rayz(p.x,p.y); profile.append({'s':s,'z':None if z is None else round(z,3)})
print('ACCESS_CONTACT_AUDIT_BEGIN')
print(json.dumps({'axis':{'EX':[round(EX.x,6),round(EX.y,6)],'EY':[round(EY.x,6),round(EY.y,6)]},'lower_collection_props':low_props,'lower_objects':low_objs,'upper_candidates':upper,'high_profile':profile},ensure_ascii=False,separators=(',',':'),default=str))
print('ACCESS_CONTACT_AUDIT_END')
